-- Hebrew-aware chain rules + cleanup of seeded Latin rules from 0002 that cannot fire or false-fire.
-- Patterns match as a substring of the normalized lowercase descriptor (classify.ts matchRule), and
-- normalizeMerchant rewrites some Latin names to Hebrew first (super pharm, amazon, netflix), so
-- those need Hebrew patterns. Short generic tokens (hot, paz) are replaced by longer specific ones.
-- Idempotent: fixed ids, and a rule is skipped when any rule with the same pattern already exists.

-- Over-broad or unreachable 0002 seeds: paz (inside unrelated words), hot (hotel), water/electric
-- (any descriptor containing them), super pharm (rewritten to Hebrew before matching).
UPDATE categorization_rules SET enabled = 0 WHERE id IN (
  '00000000-0000-4000-8000-000000000107',
  '00000000-0000-4000-8000-00000000010d',
  '00000000-0000-4000-8000-00000000010f',
  '00000000-0000-4000-8000-000000000110',
  '00000000-0000-4000-8000-000000000111'
);
--> statement-breakpoint

