INSERT OR IGNORE INTO categorization_rules (id, pattern, category_id, priority, enabled, created_at)
SELECT s.id, s.pattern, s.category_id, 10, 1, '2026-01-01T00:00:00+02:00'
FROM seed s
WHERE EXISTS (SELECT 1 FROM categories c WHERE c.id = s.category_id)
  AND NOT EXISTS (SELECT 1 FROM categorization_rules r WHERE lower(trim(r.pattern)) = lower(s.pattern));
